+        let error = render_text_with_renderer_and_spacing(
+            &bytes,
+            &request(config_16_mono(), "A", 64, 40),
+            RendererRole::Baseline,
+            spacing,
+        )
+        .unwrap_err();
+        assert_eq!(error.to_string(), TRACKING_ERROR);
+    }
+    let error = render_text_with_renderer_and_spacing(
+        b"not a font",
+        &request(config_16_mono(), "A", 64, 40),
+        RendererRole::Baseline,
+        99.0,
+    )
+    .unwrap_err();
+    assert_eq!(error.to_string(), TRACKING_ERROR);
