+        let rendered = render_text_with_renderer_and_spacing(
+            &bytes,
+            &request(config_16_mono(), "A", 64, 40),
+            RendererRole::Baseline,
+            spacing,
+        )
+        .unwrap();
+        assert_eq!((rendered.width, rendered.height), (64, 40));
