    } else {
        Vec::new()
    };
    RasterDiagnostics {
        delivered_ink_pixels: record.pixels.iter().filter(|&&v| v != 0).count(),
        delivered_topology: if valid_size == record.pixels.len() as u64 && valid_size <= 4_194_304 {
            topology(
                &record.pixels.iter().map(|&v| v != 0).collect::<Vec<_>>(),
