                .as_array()
                .unwrap()
                .iter()
                .map(|cell| cell.as_u64().unwrap() as usize)
                .collect();
            assert_eq!(cells.len(), 4);
            (cells[0], cells[1] as u16, cells[2], cells[3])
        })
