pub(crate) fn fixed(value: f32, rounding: MetricRounding) -> i32 {
    match rounding {
        MetricRounding::Subpixel => (value * 64.0).round() as i32,
        MetricRounding::Pixel => value.round() as i32 * 64,
    }
