    pen_26_6: i64,
    last: Option<u32>,
    byte_start: usize,
    byte_end: usize,
}

impl LineBuild {
    fn empty(origin: usize) -> Self {
        LineBuild {
            placed: Vec::new(),
            pen_26_6: 0,
            last: None,
            byte_start: origin,
            byte_end: origin,
        }
    }

    fn width_26_6(&self) -> Result<i32, Error> {
        i32::try_from(self.pen_26_6).map_err(|_| fail("layout advance overflow"))
    }
