    fn simulated(
        &self,
        pen: i64,
        last: Option<u32>,
        extra: &[(char, usize, usize)],
    ) -> Option<i64> {
        let mut pen = pen;
        let mut last = last;
        for (ch, _, _) in extra {
            if !self.engine.has_glyph(*ch as u32) {
                last = None;
                continue;
            }
            let (_, next) = self.engine.place(pen, last, *ch as u32)?;
            pen = next;
            last = Some(*ch as u32);
        }
        Some(pen)
    }

