fn terminal_scan_settings_fail_independently_per_field() {
    let (source, upstream) = source_and_upstream("s");
    let base = plain_candidate("s");
    let evaluation = evaluate(&source, &upstream, &base);
    assert!(
        evaluation.hard_invariants_pass,
