            .collect::<Vec<_>>(),
        vec![(
            "candidate",
            Some(cp),
            "terminal scan settings or identity inconsistent"
        )]
    );
    let mut missing = base.clone();
    missing.records[0].mono_raster = None;
    let evaluation = evaluate(&source, &upstream, &missing);
    assert_eq!(
        evaluation
            .hard_failures
            .iter()
            .map(|failure| (
                failure.report.as_str(),
