    .unwrap()
}

fn plain_candidate(characters: &str) -> ReferenceReport {
    candidate::render_with_pipeline(
        &roboto_flex(),
        &pipeline_request(characters),
        pipeline(false),
    )
    .unwrap()
}

fn applied_index(candidate: &ReferenceReport) -> usize {
