fn rescanned(record: &mut ReferenceRecord) {
    let config = Config {
        output_bits: record.output_bits,
        mono_threshold: record.mono_threshold,
        gray_gamma: record.gray_gamma,
        mono_raster: record.mono_raster.unwrap_or_default(),
