fn outline_grammar_invalid_shapes_fail_exact_invariant_and_skip_raster() {
    let (source, upstream, base) = reports("mono_1bit");
    let cases: Vec<(&str, Vec<FittedCommand>)> = vec![
        ("stray_line", vec![FittedCommand::LineTo(1.0, 0.0)]),
