#[test]
fn fitted_hinted_metrics_finite_domain() {
    let (source, upstream, base) = reports("mono_1bit");
    let valid: Vec<(Option<f32>, Option<f32>)> = vec![(None, None), (Some(8.0), Some(1.5))];
    for (width, lsb) in valid {
