                    RasterPolicy::FreeTypeMono
                } else if policy.dropout {
                    RasterPolicy::CoverageDropout
                } else {
                    RasterPolicy::Coverage
                },
                mono_rasterizer: {
                    #[cfg(feature = "candidate")]
                    {
                        policy.mono_scanner.then(MonoRasterizer::current)
                    }
