fn motion(a: &[FittedCommand], b: &[FittedCommand]) -> Option<Motion> {
    if a.len() != b.len() {
        return None;
    }
    let mut count = 0;
    let mut sum = 0.0_f64;
    let mut maximum = 0.0_f64;
    for (a, b) in a.iter().zip(b) {
        if std::mem::discriminant(a) != std::mem::discriminant(b) {
            return None;
        }
        for ((x, y), (u, v)) in coordinates(a).into_iter().zip(coordinates(b)) {
            let squared = (x - u).powi(2) + (y - v).powi(2);
            if !squared.is_finite() {
                return None;
            }
            maximum = maximum.max(squared.sqrt());
            sum += squared;
            count += 1;
        }
    }
    Some(Motion {
        coordinate_pairs: count,
        maximum_px: maximum,
        rms_px: if count == 0 {
            0.0
        } else {
            (sum / count as f64).sqrt()
        },
    })
}

use sha2::{Digest, Sha256};
use std::{fs, path::Path};

fn collect(root: &Path, directory: &Path, digest: &mut Sha256) {
    let mut entries: Vec<_> = fs::read_dir(directory)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            collect(root, &path, digest);
        } else {
            let relative = path.strip_prefix(root).unwrap().to_str().unwrap();
            let bytes = fs::read(&path).unwrap();
            digest.update((relative.len() as u64).to_le_bytes());
            digest.update(relative.as_bytes());
            digest.update((bytes.len() as u64).to_le_bytes());
            digest.update(bytes);
        }
    }
}

fn dependency_field(lock: &str, name: &str, field: &str) -> String {
    let name = format!("name = \"{name}\"");
    let field = format!("{field} = \"");
    let mut selected = false;
    for line in lock.lines().map(str::trim) {
        if line == name {
            selected = true;
        } else if selected && line.starts_with(&field) {
            return line.trim_start_matches(&field).trim_end_matches('"').into();
        } else if line == "[[package]]" {
            selected = false;
        }
    }
    "unknown".into()
}

